import { EditorView } from "@codemirror/view";

/**
 * The editor's chrome, from the tokens. Its colour comes from the
 * highlighter, through `codeHighlighting`.
 * Every value is a `var()`, read from `:root` wherever a name exists there.
 * Four names live only in `@theme inline`: `--spacing`, `--text-sm`,
 * `--text-sm--line-height` and `--font-mono`. They
 * resolve because Tailwind emits an inline theme variable whose name appears
 * in a scanned source file, and this file is one; an app that narrows its
 * `@source` must keep this folder among its sources.
 *
 * Selection and caret are the browser's own: no `drawSelection`, so no tint.
 */
export const codeTheme = EditorView.theme({
  "&": {
    color: "var(--code-text)",
    backgroundColor: "var(--code-background)",
    borderRadius: "var(--radius)",
  },
  // The global focus recipe, around the whole editor, gutter included. The
  // editor sits inside its root's hairline, so the offset adds the line
  // width: the indicator sits as far outside the hairline as a code block's.
  "&.cm-focused": {
    outline: "var(--focus-width) solid var(--ring)",
    outlineOffset: "calc(var(--focus-offset) + var(--line-width))",
  },
  ".cm-content": {
    caretColor: "var(--code-text)",
    padding: "calc(var(--spacing) * 3) 0",
  },
  ".cm-scroller": {
    fontFamily: "var(--font-mono)",
    fontSize: "var(--text-sm)",
    lineHeight: "var(--text-sm--line-height)",
    // Code shows the characters that were typed: no ligatures.
    fontVariantLigatures: "none",
    borderRadius: "var(--radius)",
    // The track is the code ground.
    scrollbarColor: "var(--input) var(--code-background)",
    scrollbarWidth: "thin",
  },
  ".cm-gutters": {
    backgroundColor: "var(--code-background)",
    color: "var(--muted-foreground)",
    borderRight: "var(--line-width) solid var(--border)",
  },
  ".cm-lineNumbers .cm-gutterElement": {
    padding: "0 calc(var(--spacing) * 2) 0 calc(var(--spacing) * 3)",
  },
  // The active line, one opaque step from the ground, not a tint.
  ".cm-activeLine": { backgroundColor: "var(--code-active-line)" },
  ".cm-activeLineGutter": { backgroundColor: "var(--code-active-line)" },
  // The base theme tints matched brackets; the tint is cleared and a hairline
  // drawn around each tells the pair.
  "&.cm-focused .cm-matchingBracket": {
    backgroundColor: "transparent",
    outline: "var(--line-width) solid var(--input)",
  },
  "&.cm-focused .cm-nonmatchingBracket": {
    backgroundColor: "transparent",
    color: "var(--destructive)",
    textDecoration: "underline wavy",
  },
  ".cm-placeholder": { color: "var(--muted-foreground)" },
  ".cm-specialChar": { color: "var(--destructive)" },
});

import { closeBrackets, closeBracketsKeymap } from "@codemirror/autocomplete";
import { defaultKeymap, history, historyKeymap } from "@codemirror/commands";
import { pythonLanguage } from "@codemirror/lang-python";
import { bracketMatching, indentOnInput } from "@codemirror/language";
import type { Extension } from "@codemirror/state";
import {
  highlightActiveLine,
  highlightActiveLineGutter,
  keymap,
  lineNumbers,
} from "@codemirror/view";
import { codeHighlighting } from "./code-editor-highlighting";

/**
 * The Python preset: line numbers, history, the default keys, Python's
 * grammar for structure (indentation, brackets), its colour from the
 * highlighter, bracket closing and matching, indent on input and the active
 * line. Python's own queries tell decorators, annotations, `self`, built-ins
 * and docstrings, so the editor colours Python exactly as a code block does.
 *
 * `pythonLanguage`, not `python()`: completion is off, so its two completion
 * sources would be inert weight. Tab is not bound, so Tab leaves the editor
 * and there is no keyboard trap; `Mod-]` and `Mod-[` indent. An app for
 * another language writes its own preset beside this one, or opens one
 * through `code-languages`.
 */
export function pythonSetup(): Extension[] {
  return [
    lineNumbers(),
    history(),
    keymap.of([...closeBracketsKeymap, ...defaultKeymap, ...historyKeymap]),
    pythonLanguage,
    codeHighlighting("python"),
    closeBrackets(),
    bracketMatching(),
    indentOnInput(),
    highlightActiveLine(),
    highlightActiveLineGutter(),
  ];
}

import { Prec, RangeSetBuilder, type Extension } from "@codemirror/state";
import {
  Decoration,
  ViewPlugin,
  type DecorationSet,
  type EditorView,
  type ViewUpdate,
} from "@codemirror/view";
import {
  CODE_ROLES,
  loadHighlighter,
  roleClasses,
  type CodeRole,
  type HighlightChange,
  type HighlightSession,
} from "$LIB$/highlighter";

/** One mark per role, with the classes a code block renders. */
const MARKS = Object.fromEntries(
  CODE_ROLES.filter((role) => role !== "text").map((role) => [
    role,
    Decoration.mark({ class: roleClasses[role] }),
  ]),
) as Record<Exclude<CodeRole, "text">, Decoration>;

/**
 * The editor's colour, from the highlighter: the same
 * session a code block streams through, so the editor colours code exactly as
 * the block does. One view plugin, at the highest precedence, so its span is
 * innermost and its class decides the colour.
 *
 * It loads the language, then opens a session on the document as it is
 * then. Each committed update passes its changes to the session, which
 * re-parses once; the marks cover the visible ranges only. Until the
 * language loads the editor shows plain text, as the prerendered fallback
 * does. Lezer, or a legacy mode, keeps indentation, brackets and the rest.
 */
export function codeHighlighting(language: string): Extension {
  return Prec.highest(
    ViewPlugin.fromClass(
      class {
        decorations: DecorationSet = Decoration.none;
        session: HighlightSession | null = null;
        stop: (() => void) | null = null;
        destroyed = false;

        constructor(readonly view: EditorView) {
          void loadHighlighter(language)
            .then((highlighter) => {
              if (!highlighter || this.destroyed) return;
              const session = highlighter.session(
                this.view.state.doc.toString(),
              );
              this.session = session;
              this.stop = session.onChange(() => this.repaint());
              this.repaint();
            })
            .catch(() => {});
        }

        /** Rebuilds the marks and asks the view to redraw once. */
        repaint() {
          if (this.destroyed || !this.session) return;
          this.decorations = this.build();
          this.view.dispatch({});
        }

        build(): DecorationSet {
          const builder = new RangeSetBuilder<Decoration>();
          if (!this.session) return builder.finish();
          for (const { from, to } of this.view.visibleRanges)
            for (const range of this.session.ranges(from, to))
              builder.add(
                range.from,
                range.to,
                MARKS[range.role as Exclude<CodeRole, "text">],
              );
          return builder.finish();
        }

        update(update: ViewUpdate) {
          if (!this.session) return;
          if (update.docChanged) {
            // `update.changes` composes every transaction the view committed
            // since the last update, so one update parses once.
            const changes: HighlightChange[] = [];
            update.changes.iterChanges((fromA, toA, fromB, toB) =>
              changes.push({ fromA, toA, fromB, toB }),
            );
            this.session.update(update.state.doc.toString(), changes);
          }
          if (update.docChanged || update.viewportChanged)
            this.decorations = this.build();
        }

        destroy() {
          this.destroyed = true;
          this.stop?.();
          this.session?.dispose();
          this.session = null;
        }
      },
      { decorations: (plugin) => plugin.decorations },
    ),
  );
}

import Root from "./code-editor.svelte";
import { codeHighlighting } from "./code-editor-highlighting";
import { pythonSetup } from "./code-editor-python";
import { codeTheme } from "./code-editor-theme";

export {
  Root,
  pythonSetup,
  codeTheme,
  codeHighlighting,
  //
  Root as CodeEditor,
};
